sys_script_include.script:
var userDuplicateRegister = Class.create();
userDuplicateRegister.prototype = {
    initialize: function() {
    },
    getAvailableCourses: function() {
        var registeredTrainingNotToBeShown = [];
		var currentUser = gs.getUserID(); // ID do usuário atual

		var today = new GlideDate();
		today.setValue(new GlideDateTime().getLocalDate().toString());
		var currentDate = today.getValue();

        var grReg = new GlideRecord('x_1329491_training_registration');
        grReg.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4");
        grReg.query();

        while (grReg.next()) {
            registeredTrainingNotToBeShown.push(grReg.training.sys_id.toString());
        }

        var registeredTrainingToBeShown = [];
        var grTraining = new GlideRecord("x_1329491_training_training_calendar");
		grTraining.addQuery('date', '>', today);
        grTraining.addQuery('instructor', '!=', currentUser); // já está filtrando qunado usuário == instrutor

        grTraining.query();

        while (grTraining.next()) {
			if (registeredTrainingNotToBeShown.indexOf(grTraining.getUniqueValue()) == -1) {
				var grRegTotalCalendar = new GlideRecord('x_1329491_training_registration');
				grRegTotalCalendar.addQuery('training', grTraining.getUniqueValue());
				grRegTotalCalendar.addQuery('state', '!=', '4');

				grRegTotalCalendar.query();

				if (grRegTotalCalendar.getRowCount() < grTraining.getValue('available_seats')) {
					var grCalendarList = new GlideRecord("x_1329491_training_training_calendar");
					var calendarList = [];
					grCalendarList.addQuery('training', grTraining.training);

					grCalendarList.query();

					while (grCalendarList.next()) {
						calendarList.push(grCalendarList.getUniqueValue());
					}

					var grRegTotalSameTraining = new GlideRecord('x_1329491_training_registration');
					grRegTotalSameTraining.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^trainingIN" + calendarList.join(','));
					//grRegTotalSameTraining.addQuery('state', '!=', '4'); reprovados não excluidos
					grRegTotalSameTraining.query();

					if (grRegTotalSameTraining.getRowCount() < 3) {

						registeredTrainingToBeShown.push(grTraining.getUniqueValue());
					}
				}

			}


        }
        return 'sys_idIN' + registeredTrainingToBeShown.join(',');
    },

    type: 'userDuplicateRegister'
};
